const navFor = (roles: string[]) => {
  const has = (role: string) => roles.includes(role);
  const names = has('SUPER_ADMIN') ? ['Overview','User Management','Project Management','Lead Management','Employee Management','Vendor Management','Finance','Payroll','Reports','System Configuration','Audit Logs'] : has('SALES_MANAGER') ? ['Overview','Lead Management','Sales Monitoring','Negotiation','Reports'] : has('SALES_EXECUTIVE') ? ['Overview','Leads','Lead Qualification','Follow-ups','Properties','Site Visits','Negotiation','Bookings','Documents','Customers'] : has('HR') ? ['Overview','Employees','Attendance','Leave','Payroll','Salary','Reports'] : has('FINANCE') ? ['Overview','Customer Payments','Loans','Agreements','Vendor Payments','Petty Cash','Reports'] : has('VENDOR') ? ['Overview','Vendors','Purchase Orders','Vendor Bills','Vendor Ledger'] : ['Overview','Complaints','Maintenance','Customers','Possession'];
  return nav.filter(item => names.includes(item.name));
};
const canCreateLead = (roles: string[]) => roles.some(role => ['SUPER_ADMIN', 'SALES_MANAGER', 'SALES_EXECUTIVE'].includes(role));
